# Seul l'Administrateur change les photos du site.
PERMISSIONS_ADMINISTRATEUR = ('view_emplacementphoto', 'change_emplacementphoto')


def creer_emplacements(apps, schema_editor):
    EmplacementPhoto = apps.get_model('core', 'EmplacementPhoto')
    for cle, page, libelle, format_conseille, largeur_max in EMPLACEMENTS:
        EmplacementPhoto.objects.get_or_create(cle=cle, defaults={
            'uuid': uuid.uuid4(), 'page': page, 'libelle': libelle,
            'format_conseille': format_conseille, 'largeur_max': largeur_max,
        })

